"""Two coordinate-map route problems. Diagrams show stops, ordered travel and the scale."""
import argparse
import json
from coordinate_positions import lesson,panel
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/coordinate-couriers.json'
STOPS={'B':(0,1),'K':(-8,1),'T':(8,1),'M':(0,7),'F':(0,-5)}


def mapping(label,stops,route='',lines='',angles=(),half=False):
    coords={k:STOPS[k] for k in stops}
    if half:coords={k:(x/2,1+(y-1)/2) for k,(x,y) in coords.items()}
    arrows=' '.join(a+b for a,b in zip(route,route[1:]))
    return panel(label,coords,lines,arrows,angles)


def courier(n,*,where,**fields):
    card=lesson(n,pages=[257,258] if n==1036 else [258,259],unit='1 см на бумажной карте, то есть 100 м на местности',**fields)
    caption='Вправо растёт x, вверх — y. Одно деление сетки исходной карты соответствует 100 м. На экране считай деления. Оранжевые стрелки показывают порядок посещения.'
    card['visualization']['caption']=caption
    model=card['visualization']['model'];model['description']=caption
    names={'B':'П' if n==1036 else 'Ск','K':'К','T':'С','M':'М','F':'Кд'}
    offsets={'O':[-2,-4.5],'B':[2,3.7],'K':[-2,3.3],'T':[2.2,3.5],'M':[2.2,3.5],'F':[2.5,-3]}
    for key,label in model['labels'].items():
        if label in offsets:model.setdefault('labelOffsets',{})[key]=offsets[label]
        if label in names:model['labels'][key]=names[label]
    card['statement']['givens']=[where,'К — кафе (−8;1), М — магазин (0;7), С — столовая (8;1).',
        'Масштаб 1:10 000, по отметке на карте одно деление равно 1 см. Между любыми двумя нужными пунктами есть прямая дорога.']
    if n==1037:card['statement']['givens'].insert(2,'Кд — кондитерская (0;−5).')
    card['review']['reviewer']='Сверено по рисункам 316–317 и страницам 257–259 издания 2023 года, включая место старта и физическую шкалу. Координаты и длины проверены по каждой дороге, масштаб и минимум дополнительно сверены с с. 398.'
    return card


def answer(card,m,key_error):
    k=m/1000;decimal=str(k).replace('.',',')
    card['answer']={'mode':'exact','accepted':[str(m),f'{m} м',f'{m}м',f'{decimal} км',f'{k} км',f'{decimal}км',f'{k}км'],
        'prompt':'Введи кратчайшую длину в метрах. Если считаешь в километрах, укажи «км».',
        'feedback':key_error+' Один сантиметр исходной карты — 10 000 см, то есть 100 м. Включи возвращение на базу.'}
    return card


def bakery():
    stops='BKTM';neutral=mapping('Отметь пекарню и три места доставки',stops)
    triangle=mapping('Расстояние между кафе и магазином',stops,lines='KB BM KM',angles=['KBM'])
    shortest=mapping('Пекарня → кафе → магазин → столовая → пекарня',stops,'BKMTB')
    long=mapping('Пекарня → магазин → кафе → столовая → пекарня',stops,'BMKTB')
    new=mapping('Новая карта: расстояния от пекарни вдвое меньше',stops,'BKMTB',half=True)
    card=courier(1036,where='П — пекарня. Она находится ровно посередине между кафе и столовой.',
        question='Из пекарни надо разнести заказы в магазин, кафе и столовую, затем вернуться в пекарню. Воспользуйся координатами остановок и масштабом карты. Какое наименьшее расстояние придётся пройти?',
        answer='Пекарня П=(0;1). Путь П→К→М→С→П имеет длину 8+10+10+8=36 делений, или 3600 м. Обратный обход даёт столько же. Если кафе и столовая идут подряд, длина полного пути составляет 40 делений.',
        hint='Сначала найди три вида дорог по симметрии. Затем реши, выгодно ли проходить от кафе сразу к столовой.',
        steps=[('Найди пекарню и длины дорог','Середина между (−8;1) и (8;1) имеет координаты (0;1). От базы до кафе и столовой по 8 делений, до магазина 6. Кафе и магазин разделяют катеты 8 и 6: длина прямой дороги √(8²+6²)=10. Столько же от магазина до столовой.','Координата середины — полусумма, расстояние определяется по двум перпендикулярным проекциям.'),
               ('Испытай обход через магазин','Поставь магазин между кафе и столовой. Тогда длина замкнутого пути П→К→М→С→П равна 8+10+10+8=36 делений. Его можно пройти в обратном направлении.','Старт и финиш обязаны совпасть, поэтому учитываются обе дороги к пекарне.'),
               ('Проверь остальные порядки','Если магазин не в середине списка остановок, кафе и столовая идут подряд; между ними 16 делений. Тогда к 16 прибавляются 6, 10 и 8 — выходит 40. Перестановка кафе и столовой или обратный обход длину не меняет. Повторный заход в пункт не сокращает прямую дорогу между соседними обязательными остановками.','Три объекта либо разделены магазином, либо кафе соседствует со столовой; эти варианты охватывают все порядки.'),
               ('Применяй масштаб после выбора пути','На исходной карте 36 см. При масштабе 1:10 000 это 360 000 см=3600 м. На новой схеме расстояния от базы до кафе и магазина равны 4 и 3 деления, наклонная дорога 5. Минимум 4+5+5+4=18 делений, или 1800 м.','Масштаб меняет все длины одним множителем, поэтому порядок кратчайшего маршрута сохраняется.')],
        frames=[neutral,triangle,shortest,long,new],cases=[triangle,shortest,long,new],
        prompts=[('Сколько делений в исходном маршруте через магазин между двумя другими остановками?','36','Сложи 8+10+10+8, включая обратную дорогу.'),('Сколько делений даст маршрут, в котором подряд идут кафе и столовая?','40','К дороге КС длины 16 прибавь 6, 10 и 8.'),('На новой карте той же шкалы кратчайший путь равен 18 делениям. Сколько это метров?','1800','В каждом делении 100 м.')])
    return answer(card,3600,'Ответ 36 дан в делениях, 4000 м соответствует обходу с дорогой между кафе и столовой.')


def warehouse():
    stops='BKTMF';neutral=mapping('Склад и четыре объекта доставки',stops)
    measure=mapping('Четыре равные стороны и два диаметра',stops,lines='KM MT TF FK KT MF')
    # K, M, T, F in cyclic order. Endpoints K and F are neighbours.
    best=mapping('Кафе → магазин → столовая → кондитерская',stops,'BKMTFB')
    opposite=mapping('Кафе и столовая в начале и конце',stops,'BKMFTB')
    both=mapping('Путь с обеими диагоналями',stops,'BKTFMB')
    new=mapping('Новая схема: радиусы 4 и 3 деления',stops,'BKMTFB',half=True)
    card=courier(1037,where='Ск — склад. Он расположен в середине отрезка от магазина до кондитерской.',
        question='Со склада надо доставить заказы в магазин, кафе, столовую и кондитерскую и вернуться на склад. Найди кратчайший путь по прямым дорогам на координатной карте. Объясни, как исключил более короткий порядок.',
        answer='Склад Ск=(0;1). Маршрут Ск→К→М→С→Кд→Ск даёт 8+10+10+10+6=44 деления, или 4400 м. Если крайние посещённые пункты противоположны, получается 48; если при соседних крайних пунктах пройдены обе диагонали — 52.',
        hint='Посмотри на крайние пункты именно в списке доставок: первый пункт следует сразу после склада, а из последнего надо вернуться на склад. На внешнем ромбе эти два пункта либо соседние, либо противоположные.',
        steps=[('Прочитай план и измерь дороги','Середина отрезка М–Кд равна (0;1). Радиусы к кафе и столовой равны 8, к магазину и кондитерской 6. Каждая из четырёх наклонных дорог между соседями имеет длину 10. Между противоположными пунктами дороги равны 16 и 12.','Наклонная дорога — гипотенуза треугольника с катетами 8 и 6.'),
               ('Выбери соседние крайние пункты','Если крайние пункты соседние, отрезки из склада и обратно дают 8+6=14. Между ними через два оставшихся пункта можно идти тремя внешними сторонами: 30. Итого 44. При перестановке двух средних пунктов используются обе диагонали и одна сторона: 16+12+10, всего 52.','После выбора первой и последней доставки остаются два возможных порядка двух средних остановок.'),
               ('Исключи противоположные крайние пункты','Если первыми и последними выбраны кафе и столовая, дороги к складу дают 16. Две средние остановки магазин и кондитерская соединяет дорога 12; ещё две стороны по 10. Всего 48. Если крайние магазин и кондитерская, получаем 12+16+20=48.','Симметрия ромба и обратный обход сохраняют длину. Обсуждены все типы порядков.'),
               ('Переведи минимум в метры','Наименьшая из длин 44, 48 и 52 равна 44 делениям, то есть 4400 м. На новой карте расстояния до базы уменьшены вдвое, но масштаб остаётся прежним. Получается 4+5+5+5+3=22 деления, или 2200 м.','При прямых дорогах лишние повторные заходы можно вычеркнуть по неравенству треугольника.')],
        frames=[neutral,measure,best,opposite,new],cases=[measure,best,opposite,both,new],prompts=[('У исходной карты сколько делений даёт самый короткий путь, если первые и последние пункты соседние?','44','Для трёх внешних сторон прибавь к 30 стоимость подъезда и возврата 14.'),('Сколько делений получится при противоположных крайних остановках?','48','Сложи две стороны по 10 и числа 12 и 16.'),('На новой схеме минимальный маршрут составляет 22 деления при 100 м в каждом. Сколько это метров?','2200','Умножь 22 на 100.')])
    return answer(card,4400,'Ответ 44 дан в делениях. При 4800 м проверь маршрут по трём соседним сторонам внешнего ромба.')


def build():return {'bookId':BOOK,'lessons':[bakery(),warehouse()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==text
    else:OUT.write_text(text)
